//! The merged walk: several curves composed into one output (#1654 K1, root rulings R19-2 to
//! R19-5).
//!
//! An output (a route column, a member fader or mute channel) hears `K` stored curves. Each curve
//! has a cursor: its cell in the plan's [`Program`], its own [`CellState`], its own jump length and
//! the grid period of its cell. The cursors' events are generated by [`CellEvents`], unchanged, and
//! merged in offset order. At every offset that has an event the caller's composition turns the
//! values the output has heard into one target `T`, and the output's own [`CellState`] decides,
//! with the same change-only, lagging and held-event rules as one cell, whether the output
//! retargets. Nothing here re-derives a cell decision: the rules are [`CellState`]'s.
//!
//! # The rules
//!
//! - **Change only.** An output retargets only when the composed target's bits change
//!   ([`Composable::same_bits`]), or a held event is outstanding, or (for a jump) the ramp in
//!   flight still lags.
//! - **Coincident events (R19-4).** Events of several curves at one offset are one retarget, over
//!   the longest ramp among them. A jump wins over a grid event at the same offset, and a seek
//!   landing over both.
//! - **Column jumps hold the value grid (R19-3).** A cursor is a [`CursorKind::Gate`] (a mute
//!   curve: its jumps are the output's gate changes) or a [`CursorKind::Value`]. When a gate jump
//!   retargets the output, and when the caller retargets it ([`Composed::retarget`]: a record's
//!   ramp, a gate change of the cell), every value cursor defers its jump to the first free sample
//!   of that ramp ([`CellState::defer_jump`], #1711 D1). Until it fires, the value cursor's grid
//!   events are held: they update the heard values (a gate event or record composes them) but the
//!   output does not retarget, so no grid
//!   event cuts the column jump short. At the jump's end each value cursor whose curve moved jumps
//!   over its own jump length to the curve at the jump's completion (the deferred jump's rule, change
//!   only, or always with a held event outstanding), and the coincident landings take the longest
//!   one (R19-4). A gate jump is never held. A free output retargets at once over the event's own
//!   ramp.
//! - **A cursor's own jumps** follow its cell's rules: the grid inside a curve's own jump is held
//!   by its own [`CellState`] unless its ramp completes later (a restart), as one cell's is.
//!
//! With one cursor and the identity composition the output's events are exactly that cell's
//! [`CellEvents`], so a single curve composes as it renders alone.
//!
//! # Realtime
//!
//! [`Composed::new`] allocates the cursor table, a boxed slice sized at bind (no fixed array, no
//! cap on `K`), on the control thread; [`Composed::bytes`] gives its bytes first. Everything else
//! is render-reachable and allocates, locks and blocks on nothing. A block's walk is bounded: each
//! step consumes at least one cursor event, so it takes at most [`Composed::max_events`] steps.

use alloc::boxed::Box;
use alloc::vec::Vec;

use crate::events::target_toward;
use crate::{CellEvents, CellState, Completion, Event, EventKind, NodeSpan, Program, SeekMode};

/// A composed target whose bits decide change only.
pub trait Composable: Copy {
    /// `true` when `self` and `other` have the same bits (`+0.0` and `-0.0` differ).
    fn same_bits(&self, other: &Self) -> bool;
}

impl Composable for f32 {
    fn same_bits(&self, other: &Self) -> bool {
        self.to_bits() == other.to_bits()
    }
}

impl Composable for bool {
    fn same_bits(&self, other: &Self) -> bool {
        self == other
    }
}

impl<T: Composable, const N: usize> Composable for [T; N] {
    fn same_bits(&self, other: &Self) -> bool {
        self.iter().zip(other).all(|(one, two)| one.same_bits(two))
    }
}

impl<A: Composable, B: Composable> Composable for (A, B) {
    fn same_bits(&self, other: &Self) -> bool {
        self.0.same_bits(&other.0) && self.1.same_bits(&other.1)
    }
}

/// What a cursor's curve is to the output.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum CursorKind {
    /// A value curve (a gain, a matrix entry, an offset): its grid is held while a column jump
    /// runs.
    Value,
    /// A gate curve (a mute): its jumps are column jumps, never held.
    Gate,
}

/// Why [`Composed::new`] refuses a cursor table.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ComposeError {
    /// No cursor.
    Empty,
    /// The cursor at `cursor` names a cell the program does not hold.
    Cell {
        /// The cursor's index in the table.
        cursor: usize,
    },
    /// The table could not be allocated.
    Allocation,
}

/// One curve of an output: its cell, kind, event state and heard value.
#[derive(Clone, Copy, Debug)]
pub struct ComposeCursor {
    cell: u32,
    kind: CursorKind,
    state: CellState,
    /// The jump length of a [`crate::JumpLength::Block`] cell for this block.
    jump: u32,
    /// The value the output has heard from this curve: its last event, held or not (R19-3).
    heard: f32,
    // The walk's scratch, meaningful only inside [`Composed::walk`].
    /// The state before the pull that produced `next`, and the offset that pull started at.
    before: CellState,
    resume: u32,
    /// The pulled event not yet merged.
    next: Option<Event>,
    /// The value shown to a held composition at the current offset.
    shown: f32,
    /// Whether the current offset merged an event of this cursor.
    consumed: bool,
    /// Whether that event was not held (the cursor's own retarget).
    moved: bool,
}

impl ComposeCursor {
    /// The cursor's cell in the plan's program.
    #[must_use]
    pub const fn cell(&self) -> u32 {
        self.cell
    }

    /// The cursor's kind.
    #[must_use]
    pub const fn kind(&self) -> CursorKind {
        self.kind
    }

    /// The cell's event state.
    #[must_use]
    pub const fn state(&self) -> &CellState {
        &self.state
    }

    /// The cell's event state, for a carry (a continued cell takes its predecessor's verbatim) or
    /// a reposition.
    pub const fn state_mut(&mut self) -> &mut CellState {
        &mut self.state
    }

    /// The value the output has heard from this curve.
    #[must_use]
    pub const fn heard(&self) -> f32 {
        self.heard
    }

    /// Sets the heard value (a carry, a placement).
    pub const fn set_heard(&mut self, value: f32) {
        self.heard = value;
    }

    /// Sets the block's jump length for a [`crate::JumpLength::Block`] cell (the caller resolves
    /// the cursor's row against the block's ramp lengths); a fixed-length cell ignores it.
    pub const fn set_jump(&mut self, jump: u32) {
        self.jump = jump;
    }
}

/// The values a composition reads: one per cursor, in table order.
#[derive(Clone, Copy)]
pub struct Heard<'a> {
    cursors: &'a [ComposeCursor],
    source: Source<'a>,
}

#[derive(Clone, Copy)]
enum Source<'a> {
    /// The heard values.
    Heard,
    /// The heard values with the current offset's held events shown.
    Shown,
    /// Each curve toward the completion of a ramp of `n` samples from `start`.
    Toward {
        program: &'a Program,
        start: i64,
        n: u32,
    },
}

/// One event of a composed output.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ComposedEvent<T> {
    /// The sample of the block the event applies at.
    pub offset: u32,
    /// The composed target.
    pub value: T,
    /// The ramp length in samples: the longest of the offset's events (`0` for a seek's
    /// [`EventKind::Set`]).
    pub ramp: u32,
    /// [`EventKind::Set`] at an exact seek landing, [`EventKind::Jump`] when a jump or a ramped
    /// landing is among the offset's events, else [`EventKind::Grid`].
    pub kind: EventKind,
    /// Only held events at this offset: the output does not retarget.
    pub held: bool,
}

/// One composed output: its cursor table and its own event state (#1654 K1).
#[derive(Debug)]
pub struct Composed<T> {
    cursors: Box<[ComposeCursor]>,
    /// The output's ramp in flight and held flag; its own target bits are unused (`target`).
    state: CellState,
    target: Option<T>,
    completion: Completion,
    /// The block begun by [`Self::start`] and its seek mode, until its events end.
    block: Option<(NodeSpan, SeekMode)>,
    /// [`Self::with_held_grid`]: every output retarget holds each value cursor's grid inside the
    /// retarget's ramp, as one cell holds its grid inside its own ramp (#1655 V2, R19-2).
    held_grid: bool,
    /// [`Self::with_jump_release`]: every jump the output emits replaces the lane's ramp, so it
    /// shortens each value cursor's hold to the jump's completion and drops its deferral, as one
    /// cell's jump does (#1655 U3 fold 1).
    jump_release: bool,
}

impl<T: Composable> Composed<T> {
    /// The bytes [`Self::new`] allocates for `cursors` cursors.
    #[must_use]
    pub const fn bytes(cursors: usize) -> usize {
        cursors.saturating_mul(size_of::<ComposeCursor>())
    }

    /// The output over `cells` (each a cell of `program` and its kind), whose ramps complete under
    /// `completion`. Every cursor is seeded with its curve's first `start_value` (the value a
    /// prepared stage holds); the output has no target until [`Self::seed`]. Control side: it
    /// allocates the table.
    ///
    /// # Errors
    ///
    /// [`ComposeError::Empty`] with no cell, [`ComposeError::Cell`] for a cell outside `program`,
    /// [`ComposeError::Allocation`] when the table cannot be allocated.
    pub fn new(
        program: &Program,
        cells: &[(u32, CursorKind)],
        completion: Completion,
    ) -> Result<Self, ComposeError> {
        if cells.is_empty() {
            return Err(ComposeError::Empty);
        }
        let mut table = Vec::new();
        table
            .try_reserve_exact(cells.len())
            .map_err(|_| ComposeError::Allocation)?;
        for (cursor, &(cell, kind)) in cells.iter().enumerate() {
            let seed = program
                .cell(cell as usize)
                .and_then(|program| program.segments().first().map(|first| first.start_value))
                .ok_or(ComposeError::Cell { cursor })?;
            let mut state = CellState::new();
            state.seed_target(seed);
            table.push(ComposeCursor {
                cell,
                kind,
                state,
                jump: 0,
                heard: seed,
                before: state,
                resume: 0,
                next: None,
                shown: seed,
                consumed: false,
                moved: false,
            });
        }
        Ok(Self {
            cursors: table.into_boxed_slice(),
            state: CellState::new(),
            target: None,
            completion,
            block: None,
            held_grid: false,
            jump_release: false,
        })
    }

    /// The output with the one-cell hold rule on its composed value (#1655 V2, R19-2: a member
    /// fader channel over its own curve and the reaching VCA curves): every retarget of the output
    /// (a grid or jump event, a ramped landing) reports its ramp to each value cursor whose own
    /// ramp in flight completes earlier ([`CellState::hold_until`]), so a cursor's grid event
    /// whose ramp would complete inside it is held and one that completes later restarts it, by
    /// the cell's own grid rule. A step of one curve then keeps its jump length while another
    /// curve rides (and the reverse); coincident events already take the longest ramp (R19-4).
    /// Without it (a route column, R19-3) a value jump leaves the other value cursors free. With
    /// one cursor the hold is the cursor's own ramp, so the output's events are still the cell's
    /// [`CellEvents`]. Control side.
    #[must_use]
    pub fn with_held_grid(mut self) -> Self {
        self.held_grid = true;
        self
    }

    /// The output with the one-cell jump rule on the holds and deferrals its lane put on every
    /// cursor (#1655 U3 fold 1: a member fader channel, with [`Self::with_held_grid`]). A lane's
    /// ramp (a record's or an adoption's, reported on every cursor with
    /// [`CellState::hold_until`] and [`Self::defer_jump`], or a retarget that `with_held_grid`
    /// reported) belongs to the composed output; one cell's discontinuity jump that emits
    /// replaces its ramp in flight and drops its deferral. So every jump the output emits (not a
    /// seek landing, not a held event) shortens each restartable value cursor's hold to the
    /// jump's completion ([`CellState::release_hold_by`]) and drops its deferral
    /// ([`CellState::clear_deferred_jump`]); a jump that emits nothing replaces no ramp and
    /// changes nothing (#1711 U1 fold 2). Without it (a route column) a held value follows the
    /// column's current free time and never moves earlier (#1654 T3). Control side.
    #[must_use]
    pub fn with_jump_release(mut self) -> Self {
        self.jump_release = true;
        self
    }
}

// REALTIME_POLICY_BEGIN
impl Heard<'_> {
    /// How many values there are (the cursors).
    #[must_use]
    pub const fn len(&self) -> usize {
        self.cursors.len()
    }

    /// `true` with no value.
    #[must_use]
    pub const fn is_empty(&self) -> bool {
        self.cursors.is_empty()
    }

    /// The value of cursor `index`; `0.0` outside the table.
    #[must_use]
    pub fn value(&self, index: usize) -> f32 {
        let Some(cursor) = self.cursors.get(index) else {
            return 0.0;
        };
        match self.source {
            Source::Heard => cursor.heard,
            Source::Shown => cursor.shown,
            // A gate is heard as it is: its value holds until its next jump.
            Source::Toward { .. } if cursor.kind == CursorKind::Gate => cursor.heard,
            Source::Toward { program, start, n } => {
                program
                    .cell(cursor.cell as usize)
                    .map_or(cursor.heard, |cell| {
                        // Read as placed at `start` (a fresh output's first block has not placed
                        // its cursors yet): the next discontinuity after `start` clips the value.
                        let mut state = cursor.state;
                        state.reposition(&cell, start);
                        target_toward(&cell, &state, start, n)
                    })
            }
        }
    }
}

impl<T: Composable> Composed<T> {
    /// The cursors, in table order.
    #[must_use]
    pub fn cursors(&self) -> &[ComposeCursor] {
        &self.cursors
    }

    /// The cursor at `index`.
    pub fn cursor_mut(&mut self, index: usize) -> Option<&mut ComposeCursor> {
        self.cursors.get_mut(index)
    }

    /// Every cursor, for a per-block jump length or a carry.
    pub fn cursors_mut(&mut self) -> &mut [ComposeCursor] {
        &mut self.cursors
    }

    /// The output's current target.
    #[must_use]
    pub const fn target(&self) -> Option<T> {
        self.target
    }

    /// Sets the output's target to `target`, as a completed retarget: no held event is
    /// outstanding, the ramp in flight is kept.
    pub fn seed_target(&mut self, target: T) {
        self.target = Some(target);
        // The output's state holds no target bits of its own (`target` is `T`); the seed clears
        // an outstanding held event and keeps the ramp in flight, as a cell's seed does.
        self.state.seed_target(0.0);
    }

    /// Forgets the output's target: its next grid or jump event retargets whatever its value (the
    /// one-cell rule of a fresh state, for a stage that only remembered a gain, #1638 D2). The
    /// ramp in flight is kept.
    pub fn clear_target(&mut self) {
        self.target = None;
    }

    /// The output's own event state (its ramp in flight and held flag), for a carry.
    #[must_use]
    pub const fn output_state(&self) -> &CellState {
        &self.state
    }

    /// Sets the output's own event state and target (a carry of a predecessor's output, or of a
    /// single cell's state with no target); the cursors are untouched.
    pub fn set_output(&mut self, state: CellState, target: Option<T>) {
        self.state = state;
        self.target = target;
    }

    /// Seeds the output's target with the composition of the heard values (preparation).
    pub fn seed(&mut self, compose: impl FnOnce(Heard<'_>) -> T) {
        let value = compose(self.heard(Source::Heard));
        self.seed_target(value);
    }

    /// The composition of the heard values.
    pub fn compose_heard(&self, compose: impl FnOnce(Heard<'_>) -> T) -> T {
        compose(self.heard(Source::Heard))
    }

    /// The composition of every value curve toward the completion of a ramp of `n` samples from
    /// node time `start` (the curve at that completion, never past its next discontinuity), with
    /// every gate as heard: the target of a record that retargets the output over its own ramp
    /// (#1649 D3 on a composed output).
    /// Reads the cursors' positions, so call it at a block entry, after the block's placement.
    pub fn compose_toward(
        &self,
        program: &Program,
        start: i64,
        n: u32,
        compose: impl FnOnce(Heard<'_>) -> T,
    ) -> T {
        compose(self.heard(Source::Toward { program, start, n }))
    }

    const fn heard<'a>(&'a self, source: Source<'a>) -> Heard<'a> {
        Heard {
            cursors: &self.cursors,
            source,
        }
    }

    /// A column jump the caller started at node time `start` over `n` samples (a record's ramp, a
    /// gate change of the cell): the output takes `target`, and every value cursor defers its jump
    /// to the ramp's first free sample (R19-3), so its grid is held until then and it lands over
    /// its own jump length if its curve moved. With `n = 0` nothing is in flight and nothing is
    /// deferred. Call it between blocks.
    pub fn retarget(&mut self, target: T, start: i64, n: u32) {
        self.target = Some(target);
        self.state.commit_ramp(self.completion, start, n);
        if let Some(free) = self.state.free_after(self.completion) {
            for cursor in self.cursors.iter_mut() {
                if cursor.kind == CursorKind::Value {
                    cursor.state.defer_jump(free);
                }
            }
        }
    }

    /// Defers every value cursor's jump to node time `at` ([`CellState::defer_jump`]): the
    /// output's ramp in flight was adopted at a plan swap and its curves moved (#1711 D1, R19-5).
    /// Call it between blocks.
    pub fn defer_jump(&mut self, at: i64) {
        for cursor in self.cursors.iter_mut() {
            if cursor.kind == CursorKind::Value {
                cursor.state.defer_jump(at);
            }
        }
    }

    /// Drops every value cursor's pending deferral ([`CellState::clear_deferred_jump`]): the ramp
    /// it waits for was replaced or ended early.
    pub fn clear_deferred_jump(&mut self) {
        for cursor in self.cursors.iter_mut() {
            if cursor.kind == CursorKind::Value {
                cursor.state.clear_deferred_jump();
            }
        }
    }

    /// Takes `other`'s cursor states, heard values and output state (a twin bound over the same
    /// cells: a probe walk's copy). Returns `false`, copying nothing, when the tables differ in
    /// length.
    pub fn copy_from(&mut self, other: &Self) -> bool {
        if self.cursors.len() != other.cursors.len() {
            return false;
        }
        self.cursors.copy_from_slice(&other.cursors);
        self.state = other.state;
        self.target = other.target;
        self.completion = other.completion;
        self.block = other.block;
        self.held_grid = other.held_grid;
        self.jump_release = other.jump_release;
        true
    }

    /// The most events one block of `frames` samples can give: the sum of the cursors' bounds
    /// ([`crate::CellProgram::max_events`]); the walk takes at most this many steps.
    #[must_use]
    pub fn max_events(&self, program: &Program, frames: u32) -> u32 {
        self.cursors
            .iter()
            .filter_map(|cursor| program.cell(cursor.cell as usize))
            .fold(0_u32, |sum, cell| {
                sum.saturating_add(cell.max_events(frames))
            })
    }

    /// The events of the block `span` in increasing offset, at most one per offset, each passed
    /// to `emit`; `compose` turns the heard values into the output's target. Every cursor's state
    /// advances through the block. A cursor whose cell the program does not hold gives no event.
    /// [`Self::start`] then [`Self::next_event`] until `None`.
    pub fn walk(
        &mut self,
        program: &Program,
        span: NodeSpan,
        mode: SeekMode,
        mut compose: impl FnMut(Heard<'_>) -> T,
        mut emit: impl FnMut(ComposedEvent<T>),
    ) {
        self.start(program, span, mode);
        while let Some(event) = self.next_event(program, &mut compose) {
            emit(event);
        }
    }

    /// Begins the block `span`: each cursor pulls its first event. The block's events then come
    /// out of [`Self::next_event`], one at a time, so a caller can merge several outputs' events
    /// in offset order (a route's two columns).
    pub fn start(&mut self, program: &Program, span: NodeSpan, mode: SeekMode) {
        let frames = span.frames();
        self.block = Some((span, mode));
        for cursor in self.cursors.iter_mut() {
            cursor.next = None;
            cursor.consumed = false;
            cursor.shown = cursor.heard;
            pull(cursor, program, &span, mode, 0, frames);
        }
    }

    /// The block's next event, or `None` at its end (or with no block begun): every offset with
    /// cursor events is merged and decided in order until one gives the output an event. Bounded:
    /// each merged offset consumes at least one cursor event.
    pub fn next_event(
        &mut self,
        program: &Program,
        mut compose: impl FnMut(Heard<'_>) -> T,
    ) -> Option<ComposedEvent<T>> {
        let (span, mode) = self.block?;
        let frames = span.frames();
        while let Some(offset) = self
            .cursors
            .iter()
            .filter_map(|cursor| cursor.next.map(|event| event.offset))
            .min()
        {
            let Some(time) = span.time_at(offset) else {
                break;
            };
            let merged = merge(&mut self.cursors, offset);
            let landing = span.step_offset() == Some(offset) && (merged.set || merged.jump);
            let event = self.decide(landing, offset, time, merged, &mut compose);
            // R19-3: a gate's jump that retargets the output is a column jump; a seek landing is
            // not (every cursor landed itself).
            let column_jump =
                merged.gate_jump && !landing && event.is_some_and(|event| !event.held);
            let retargeted = !landing && event.is_some_and(|event| !event.held);
            let free = if retargeted {
                self.state.free_after(self.completion)
            } else {
                None
            };
            // `with_held_grid`: the completion of the ramp this offset retargets the output over
            // (a landing too), which every value cursor holds its grid inside.
            let hold = event
                .filter(|event| self.held_grid && !event.held && event.ramp > 0)
                .map(|event| crate::completion_of(self.completion, time, event.ramp));
            // `with_jump_release`: the completion of the jump this offset emits, which replaces
            // the lane's ramp on every value cursor.
            let release = event
                .filter(|event| {
                    self.jump_release && !landing && !event.held && event.kind == EventKind::Jump
                })
                .map(|event| crate::completion_of(self.completion, time, event.ramp));
            let completion = self.completion;
            let short = |state: &CellState, hold: i64| {
                state.free_after(completion).is_none_or(|free| free <= hold)
            };
            // Whether the release changes `state`: a hold past `at` or a pending deferral.
            let releases = |state: &CellState, at: i64| {
                let mut released = *state;
                released.release_hold_by(at);
                state.deferred_jump().is_some()
                    || released.free_after(completion) != state.free_after(completion)
            };
            let next = offset.saturating_add(1);
            for cursor in self.cursors.iter_mut() {
                cursor.shown = cursor.heard;
                let value = cursor.kind == CursorKind::Value;
                // A value cursor deferred to the end of a column ramp that this retarget replaced
                // and outlasts (another curve's own jump) waits for the new ramp's end instead:
                // its landing never cuts a ramp short (R19-3). The cursor whose own event this
                // is follows its own cell's rules.
                let pending = if cursor.consumed {
                    cursor.state.deferred_jump()
                } else {
                    cursor.before.deferred_jump()
                };
                let released = release.filter(|&at| {
                    value
                        && program
                            .cell(cursor.cell as usize)
                            .is_some_and(|cell| !cell.no_restart)
                        && releases(
                            if cursor.consumed {
                                &cursor.state
                            } else {
                                &cursor.before
                            },
                            at,
                        )
                });
                let extend = free.filter(|&free| {
                    !column_jump
                        && released.is_none()
                        && !cursor.moved
                        && pending.is_some_and(|at| at > time && at < free)
                });
                let defer = if column_jump { free } else { extend };
                // The hold reaches a cursor whose own ramp in flight completes earlier: for one
                // that pulled ahead, the state its pull started from.
                let held = hold.filter(|&hold| {
                    value
                        && short(
                            if cursor.consumed {
                                &cursor.state
                            } else {
                                &cursor.before
                            },
                            hold,
                        )
                });
                if value && (defer.is_some() || held.is_some() || released.is_some()) {
                    if !cursor.consumed {
                        // The cursor pulled past this offset before the column ramp changed:
                        // replay its pull up to here (it gave no event there), then release,
                        // defer (or hold) and pull again.
                        replay(cursor, program, &span, mode, next);
                    }
                    if let Some(at) = released {
                        cursor.state.release_hold_by(at);
                        cursor.state.clear_deferred_jump();
                    }
                    if let Some(hold) = held
                        && short(&cursor.state, hold)
                    {
                        cursor.state.hold_until(hold);
                    }
                    if let Some(free) = defer {
                        cursor.state.defer_jump(free);
                    }
                    pull(cursor, program, &span, mode, next, frames);
                } else if cursor.consumed {
                    pull(cursor, program, &span, mode, next, frames);
                }
                cursor.consumed = false;
                cursor.moved = false;
            }
            if event.is_some() {
                return event;
            }
        }
        self.block = None;
        None
    }

    /// The output's decision at `offset` (node time `time`) over the events `merged` there;
    /// `landing` when they are the block's seek landings.
    fn decide(
        &mut self,
        landing: bool,
        offset: u32,
        time: i64,
        merged: Merged,
        compose: &mut impl FnMut(Heard<'_>) -> T,
    ) -> Option<ComposedEvent<T>> {
        let event = |value, ramp, kind, held| ComposedEvent {
            offset,
            value,
            ramp,
            kind,
            held,
        };
        if landing {
            // A seek landing: every cursor landed here, and a landing always emits.
            let value = compose(self.heard(Source::Heard));
            self.state.clear_for_landing();
            let kind = if merged.set {
                EventKind::Set
            } else {
                EventKind::Jump
            };
            let ramp = if merged.set { 0 } else { merged.ramp };
            self.commit(value, time, ramp);
            return Some(event(value, ramp, kind, false));
        }
        if merged.jump || merged.grid {
            let value = compose(self.heard(Source::Heard));
            let same = self.target.is_some_and(|target| target.same_bits(&value));
            let lagging = merged.jump && self.state.lagging(self.completion, time, merged.ramp);
            if self.state.unchanged_with(same) && !lagging {
                return None;
            }
            self.commit(value, time, merged.ramp);
            let kind = if merged.jump {
                EventKind::Jump
            } else {
                EventKind::Grid
            };
            return Some(event(value, merged.ramp, kind, false));
        }
        if merged.held {
            let value = compose(self.heard(Source::Shown));
            let differs = !self.target.is_some_and(|target| target.same_bits(&value));
            if self.state.hold_event(differs) {
                return Some(event(value, merged.held_ramp, EventKind::Grid, true));
            }
        }
        None
    }

    fn commit(&mut self, value: T, time: i64, ramp: u32) {
        self.target = Some(value);
        self.state.commit_ramp(self.completion, time, ramp);
    }
}

/// What one offset's events were: the kinds of the events that were not held, the longest ramp
/// among them (R19-4), whether a gate's jump is among them, and the held events' longest ramp.
#[derive(Clone, Copy, Default)]
struct Merged {
    set: bool,
    jump: bool,
    grid: bool,
    gate_jump: bool,
    ramp: u32,
    held: bool,
    held_ramp: u32,
}

/// Take every cursor's event at `offset`: every event is heard (R19-3: a held grid event updates
/// the heard values and does not retarget the output, so a later gate event or record composes
/// the grid's value, U2 fold 1), and a held one is also shown to the held-event rule.
fn merge(cursors: &mut [ComposeCursor], offset: u32) -> Merged {
    let mut merged = Merged::default();
    for cursor in cursors.iter_mut() {
        let Some(event) = cursor.next.filter(|event| event.offset == offset) else {
            continue;
        };
        cursor.next = None;
        cursor.consumed = true;
        cursor.moved = !event.held;
        cursor.shown = event.value;
        cursor.heard = event.value;
        if event.held {
            merged.held = true;
            merged.held_ramp = merged.held_ramp.max(event.ramp);
            continue;
        }
        merged.ramp = merged.ramp.max(event.ramp);
        match event.kind {
            EventKind::Set => merged.set = true,
            EventKind::Jump => {
                merged.jump = true;
                merged.gate_jump |= cursor.kind == CursorKind::Gate;
            }
            EventKind::Grid => merged.grid = true,
        }
    }
    merged
}

/// Pull `cursor`'s next event at or after offset `from` of the block `span` (`frames` long),
/// remembering the state it started from.
fn pull(
    cursor: &mut ComposeCursor,
    program: &Program,
    span: &NodeSpan,
    mode: SeekMode,
    from: u32,
    frames: u32,
) {
    cursor.before = cursor.state;
    cursor.resume = from;
    cursor.next = None;
    let (Some(cell), Some(window)) = (
        program.cell(cursor.cell as usize),
        span.window(from, frames),
    ) else {
        return;
    };
    cursor.next = CellEvents::new(cell, &mut cursor.state, window, mode, cursor.jump)
        .next()
        .map(|event| Event {
            offset: event.offset.saturating_add(from),
            ..event
        });
}

/// Return `cursor` to the state its last pull started from and run the block's offsets up to
/// `to` again, where that pull found no event, so the state is the one a stream stopped at `to`
/// would hold.
fn replay(cursor: &mut ComposeCursor, program: &Program, span: &NodeSpan, mode: SeekMode, to: u32) {
    cursor.state = cursor.before;
    cursor.next = None;
    let (Some(cell), Some(window)) = (
        program.cell(cursor.cell as usize),
        span.window(cursor.resume, to),
    ) else {
        return;
    };
    let mut events = CellEvents::new(cell, &mut cursor.state, window, mode, cursor.jump);
    // The pull found its first event after `to`, so the replay gives none; drained to its end.
    for _ in events.by_ref() {}
}
